// Package releasename is the ONE shared release-name grammar: the role-keyed
// vocabulary, the two-part bracket rule, the season-marker set, and the
// series + episode grammars behind a structured emission (Result). Every
// parser plugin and the serial scanner consume it as thin adapters, so all
// binaries parse release names identically. The package imports nothing
// project-internal — it is a shared leaf alongside proto/ and pkg/sdk.
package releasename

import (
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

// Result is the structured emission of one start-to-end parse. Honesty rules:
// a season with no marker is Season 0 with SeasonExplicit false (the adapter
// owns its default — serial maps 0 → 1 at confidence 0.6); an episode number
// below 1 is Episode 0; release fields with no matching token are absent
// values, never zeroed stand-ins. Singular roles (resolution/source/year)
// take the LAST matching token; list roles (codec/language) keep token order.
type Result struct {
	Title          string
	Season         int    // 0 = no marker; >= 1 when SeasonExplicit
	SeasonExplicit bool   // marker (incl. trailing roman II-IX) was present
	Episode        int    // 0 = no episode number (incl. below-1 bare forms)
	EpisodeEnd     int    // 0 = no multi-episode end
	Resolution     string // last resolution token, e.g. "1080p"
	Source         string // last source token, e.g. "web-dl"
	Codecs         []string
	Languages      []string
	Year           int // 0 = none
}

// ParseName parses a raw series/film NAME (a serial directory name, or a
// file-backed serial's raw file name — extension stripped) start-to-end:
// title, season, and the release fields. A name carrying no season and no
// episode parses as the degenerate film case: title plus release fields,
// Season 0, Episode 0.
func ParseName(name string) Result {
	raw := stripVideoExt(name)
	res := Result{}
	res.Resolution, res.Source, res.Codecs, res.Languages, res.Year = scanReleaseTags(raw)
	stripped := stripBracketSegments(raw)
	if cut, n, ok := cutSeasonMarker(stripped); ok {
		stripped, res.Season, res.SeasonExplicit = cut, n, true
	}
	stripped = stripReleaseTagTokens(stripped)
	if !res.SeasonExplicit {
		if m := romanSequelRe.FindStringSubmatchIndex(stripped); m != nil {
			res.Season = romanSeasons[strings.ToLower(stripped[m[2]:m[3]])]
			res.SeasonExplicit = true
			stripped = stripped[:m[0]]
		}
	}
	stripped = cutTrailingGroupTag(stripped)
	res.Title = cleanTitle(stripped)
	if res.Title == "" {
		res.Title = cleanTitle(name) // a name that was ONLY a token still yields its cleaned form
	}
	return res
}

// ParseEpisodeName parses a library-relative EPISODE path: the stem's episode
// grammar (SxxExx first, then the bare-number forms), with the season falling
// back to the series directory's inference, else 0 — the adapter decides its
// default. Title and release fields come from the stem.
func ParseEpisodeName(relPath, seriesDir string) Result {
	stem := strings.TrimSuffix(filepath.Base(relPath), filepath.Ext(relPath))
	res := Result{}
	res.Resolution, res.Source, res.Codecs, res.Languages, res.Year = scanReleaseTags(stem)
	if m := seasonEpisodeRe.FindStringSubmatch(stem); m != nil {
		res.Season, res.SeasonExplicit = atoi(m[1]), true
		res.Episode = atoi(m[2])
		if m[3] != "" {
			res.EpisodeEnd = atoi(m[3])
		}
	} else if ep, found := bareEpisodeNumberOf(stem); found {
		res.Episode = ep
		res.Season, res.SeasonExplicit = episodeSeasonOf(stem, seriesDir)
	}
	res.Title = episodeTitle(stem)
	return res
}

// EpisodeNumberOf is the scanner-side episode index entry point: season,
// number, sxxexx basis, ok — the sidecar association grammar. ok=false when
// the stem yields no episode number (a skipped association, not an error).
func EpisodeNumberOf(stem string) (season, number int, sxxexx, ok bool) {
	if m := seasonEpisodeRe.FindStringSubmatch(stem); m != nil {
		return atoi(m[1]), atoi(m[2]), true, true
	}
	n, found := bareEpisodeNumberOf(stem)
	if !found {
		return 0, 0, false, false
	}
	s, _ := stemSeasonMarker(stem)
	return s, n, false, true
}

// Grammar tables — compiled regexes never assume ASCII: a Cyrillic directory
// name parses correctly; the season tokens are ASCII and the title is
// whatever surrounds them (Unicode-first-class serial names).
var (
	// seasonEpisodeRe captures S01E01 plus an optional S01E01E02 (episode_end).
	// ASCII digit classes leave non-ASCII titles untouched.
	seasonEpisodeRe = regexp.MustCompile(`(?i)s(\d{1,3})e(\d{1,3})(?:e(\d{1,3}))?`)
	// seasonTokenRe finds a standalone Sxx season marker in a DIRECTORY name,
	// preceded by start-of-string or a separator. A following episode digit or
	// 'e' disqualifies the match (that is an SxxExx token) — checked in code,
	// since Go's regexp has no lookahead.
	seasonTokenRe = regexp.MustCompile(`(?i)(?:^|[\s._\-\[(])s(\d{1,3})`)
	// nthSeasonRe matches the "4th Season" directory-marker form.
	nthSeasonRe = regexp.MustCompile(`(?i)(\d{1,2})(?:st|nd|rd|th)[\s._-]*season`)
	// seasonWordRe matches the "Season 2" word-form marker, beside the
	// "4th Season" ordinal form.
	seasonWordRe = regexp.MustCompile(`(?i)(?:^|[\s._\-\[(])season[\s._-]*(\d{1,2})(?:$|[\s._\-\])])`)
	// tvSeasonRe matches a whole-token "TV <N>" season marker; the separator
	// between TV and the number is a space, hyphen, or dot.
	tvSeasonRe = regexp.MustCompile(`(?i)(?:^|[\s._\-\[(])tv[\s._-]*(\d{1,2})(?:$|[\s._\-\])])`)
	// romanSequelRe matches a trailing whole-token roman sequel suffix, II-IX
	// only — single-letter romans (I, V, X) are excluded.
	romanSequelRe = regexp.MustCompile(`(?i)(?:^|[\s._\-\[(])(II|III|IV|VI|VII|VIII|IX)[\s._\-\])]*$`)
	// cyrillicEpisodeRe matches the "<N> серия" episode marker.
	cyrillicEpisodeRe = regexp.MustCompile(`(?i)(\d{1,3})[\s._-]*серия`)
	// bareNumberRe captures a standalone 1-3 digit number (non-digit on each
	// side); 4-digit runs (years, CRC hex digits) are not episode numbers.
	bareNumberRe = regexp.MustCompile(`(?:^|[^0-9])([0-9]{1,3})(?:[^0-9]|$)`)
	// pureNumberBracketRe matches a PURE-number [NN]/(NN) bracket ANYWHERE in
	// a stem (pure digits only, so [1080p] and [C48E56C8] never match).
	pureNumberBracketRe = regexp.MustCompile(`[\[(]([0-9]{1,3})[\])]`)
	// trailingNumberRe matches a trailing bare episode number plus its
	// surrounding separators, for the season-marker probe.
	trailingNumberRe = regexp.MustCompile(`[\s._\-]*[0-9]{1,3}[\s._\-]*$`)
	// yearTokenRe matches a delimiter-bounded bare release year for emission.
	yearTokenRe = regexp.MustCompile(`(?i)(?:^|[\s._\-\[(])((?:19|20)\d{2})(?:$|[\s._\-\])])`)
)

// romanSeasons maps the accepted sequel suffixes (lowercased) to their season
// values. Range II-IX.
var romanSeasons = map[string]int{
	"ii": 2, "iii": 3, "iv": 4, "vi": 6, "vii": 7, "viii": 8, "ix": 9,
}

// videoExtensions is the trailing-extension set a file-backed serial name may
// carry; directory names carry none and pass through unchanged.
var videoExtensions = map[string]bool{
	".mkv": true, ".mp4": true, ".m4v": true, ".mov": true, ".avi": true,
	".webm": true, ".wmv": true, ".flv": true, ".mpg": true, ".mpeg": true,
	".ts": true, ".m2ts": true,
}

// stripVideoExt drops a trailing video extension from a file-backed serial
// name; directory names carry no video extension and pass through unchanged.
func stripVideoExt(name string) string {
	ext := filepath.Ext(name)
	if videoExtensions[strings.ToLower(ext)] {
		return strings.TrimSuffix(name, ext)
	}
	return name
}

// cutSeasonMarker finds the first anchored season marker in a name and returns
// the name with that marker's span replaced by a space, its number, and true.
// Priority: Nth Season, Season N, standalone Sxx, TV <N>. Anchored forms only
// — an internal digit ("Title_3_The_End") or a trailing bare digit ("Title 0")
// is never a marker.
func cutSeasonMarker(name string) (rest string, n int, ok bool) {
	for _, re := range []*regexp.Regexp{nthSeasonRe, seasonWordRe} {
		if m := re.FindStringSubmatchIndex(name); m != nil {
			return spliceCut(name, m[0], m[1]), atoi(name[m[2]:m[3]]), true
		}
	}
	if m := seasonTokenIndex(name); m != nil {
		return spliceCut(name, m[0], m[1]), atoi(name[m[2]:m[3]]), true
	}
	if m := tvSeasonRe.FindStringSubmatchIndex(name); m != nil {
		return spliceCut(name, m[0], m[1]), atoi(name[m[2]:m[3]]), true
	}
	return name, 0, false
}

// spliceCut replaces name[start:end] with a single space.
func spliceCut(name string, start, end int) string {
	return name[:start] + " " + name[end:]
}

// seasonTokenIndex returns the match indices of the first standalone Sxx
// marker, or nil. An Sxx immediately followed by an episode digit or 'e' (an
// SxxExx episode token) or by a further digit (a longer number) is skipped.
func seasonTokenIndex(s string) []int {
	for _, loc := range seasonTokenRe.FindAllStringSubmatchIndex(s, -1) {
		if loc[3] < len(s) {
			switch c := s[loc[3]]; {
			case c == 'e' || c == 'E' || (c >= '0' && c <= '9'):
				continue // an episode token or a longer number — not a season marker
			}
		}
		return loc
	}
	return nil
}

// bareEpisodeNumberOf extracts the episode number a stem carries WITHOUT an
// SxxExx token: the first of a "<N> серия" marker, a pure-number bracket, or
// the last standalone 1-3 digit number after bracket segments and resolution
// tokens are stripped (last number wins — the sidecar bare-number convention).
// The pure-number bracket is a candidate WHEREVER it occurs in the stem and
// the rightmost one wins, so a trailing decoration bracket ("Show_II_[01]_
// [HEVC]") no longer displaces the episode number. A number below 1 is no
// number (a "Title 0" stays numberless).
func bareEpisodeNumberOf(stem string) (episode int, ok bool) {
	if m := cyrillicEpisodeRe.FindStringSubmatch(stem); m != nil {
		if n := atoi(m[1]); n > 0 {
			return n, true
		}
		return 0, false
	}
	if brackets := pureNumberBracketRe.FindAllStringSubmatchIndex(stem, -1); len(brackets) > 0 {
		last := brackets[len(brackets)-1]
		if n := atoi(stem[last[2]:last[3]]); n > 0 {
			return n, true
		}
		return 0, false
	}
	reduced := resolutionRe.ReplaceAllString(bracketSegmentRe.ReplaceAllString(stem, " "), " ")
	matches := bareNumberRe.FindAllStringSubmatch(reduced, -1)
	if len(matches) == 0 {
		return 0, false
	}
	if n := atoi(matches[len(matches)-1][1]); n > 0 {
		return n, true
	}
	return 0, false
}

// episodeSeasonOf resolves an episode's season when its number did not come
// from an SxxExx token: the stem's own season marker, else the series
// directory's inference, else 0 (the adapter owns its default).
func episodeSeasonOf(stem, seriesDir string) (season int, explicit bool) {
	if n, ok := stemSeasonMarker(stem); ok {
		return n, true
	}
	if seriesDir != "" {
		if r := ParseName(seriesDir); r.SeasonExplicit {
			return r.Season, true
		}
	}
	return 0, false
}

// stemSeasonMarker applies the season-marker rules to an episode stem:
// bracket segments, release tags, and a trailing group tag stripped, then the
// anchored markers; the trailing roman sequel is checked after the episode's
// own trailing number is removed, so "[Group] Title II 01 [BDrip …]" infers
// season 2.
func stemSeasonMarker(stem string) (season int, ok bool) {
	name := stripBracketSegments(stem)
	name = stripReleaseTagTokens(name)
	if _, n, found := cutSeasonMarker(name); found {
		return n, true
	}
	name = cutTrailingGroupTag(name)
	name = cutTrailingBareNumber(name)
	if m := romanSequelRe.FindStringSubmatchIndex(name); m != nil {
		return romanSeasons[strings.ToLower(name[m[2]:m[3]])], true
	}
	return 0, false
}

// cutTrailingBareNumber removes a trailing bare episode number and its
// surrounding separators, so the roman-sequel check sees the title tokens.
func cutTrailingBareNumber(name string) string {
	return trailingNumberRe.ReplaceAllString(name, "")
}

// episodeTitle derives a display title from an episode stem: brackets, the
// SxxExx token, release tags, a trailing group tag, a trailing episode
// number, and a trailing roman sequel all cut; the rest cleaned.
func episodeTitle(stem string) string {
	name := stripBracketSegments(stem)
	if m := seasonEpisodeRe.FindStringSubmatchIndex(name); m != nil {
		name = spliceCut(name, m[0], m[1])
	}
	name = stripReleaseTagTokens(name)
	name = cutTrailingGroupTag(name)
	if m := trailingNumberRe.FindStringSubmatchIndex(name); m != nil &&
		!(m[0] > 0 && isDigit(name[m[0]-1])) {
		name = name[:m[0]] // a trailing bare episode number is not title text
	}
	if m := romanSequelRe.FindStringSubmatchIndex(name); m != nil {
		name = name[:m[0]]
	}
	if t := cleanTitle(name); t != "" {
		return t
	}
	return cleanTitle(stem)
}

// isDigit reports whether c is an ASCII digit.
func isDigit(c byte) bool { return c >= '0' && c <= '9' }

// tagPattern is one flexible-separator release-tag pattern with its role and
// canonical (table-form) value.
type tagPattern struct {
	role  string
	value string
	re    *regexp.Regexp
}

// roleTagPatterns is releaseTagPatterns keyed back to its role, so emission
// can attribute each whole-token match (canonical table form — "WEBDL"
// emits as "web-dl").
var roleTagPatterns = buildRoleTagPatterns()

func buildRoleTagPatterns() []tagPattern {
	seen := make(map[string]bool, len(releaseTagSet))
	pats := make([]tagPattern, 0, len(releaseTagSet))
	for role, tags := range releaseTagTokens {
		for _, tag := range tags {
			if seen[tag] {
				continue
			}
			seen[tag] = true
			flex := strings.ReplaceAll(regexp.QuoteMeta(tag), "-", `[._\- ]?`)
			pats = append(pats, tagPattern{
				role:  role,
				value: tag,
				re:    regexp.MustCompile(`(?i)(?:^|[\s._\-\[(])` + flex + `(?:$|[\s._\-\])])`),
			})
		}
	}
	return pats
}

// tagHit is one matched release tag at its byte offset in the raw name.
type tagHit struct {
	start int
	role  string
	value string
}

// scanReleaseTags extracts the release fields a raw name carries: singular
// roles last-wins, list roles in token order (matches sorted by offset), plus
// the delimiter-bounded bare year (last one wins).
func scanReleaseTags(name string) (resolution, source string, codecs, languages []string, year int) {
	var hits []tagHit
	for _, p := range roleTagPatterns {
		for _, loc := range p.re.FindAllStringIndex(name, -1) {
			hits = append(hits, tagHit{start: loc[0], role: p.role, value: p.value})
		}
	}
	sort.Slice(hits, func(i, j int) bool { return hits[i].start < hits[j].start })
	for _, h := range hits {
		switch h.role {
		case "resolution":
			resolution = h.value // last matching token wins
		case "source":
			source = h.value // last matching token wins
		case "codec":
			codecs = append(codecs, h.value)
		case "language":
			languages = append(languages, h.value)
		}
	}
	if years := yearTokenRe.FindAllStringSubmatch(name, -1); len(years) > 0 {
		year = atoi(years[len(years)-1][1])
	}
	return resolution, source, codecs, languages, year
}

// cleanTitle normalizes separators (".", "_", surrounding "-") to spaces,
// collapses whitespace, and trims. It preserves non-ASCII (Cyrillic, etc.).
func cleanTitle(s string) string {
	s = strings.NewReplacer(".", " ", "_", " ").Replace(s)
	s = strings.TrimSpace(s)
	s = strings.Trim(s, "- ")
	fields := strings.Fields(s)
	return strings.Join(fields, " ")
}

// atoi parses a decimal integer, returning 0 on any failure (digits come from
// regexp captures, so failure here is unexpected — 0 is a safe fallback).
func atoi(s string) int {
	n, _ := strconv.Atoi(s)
	return n
}
